const int maxn = 1e5 + 5;
int a[maxn];
int maxl[maxn];
int maxr[maxn];
int spf[maxn];         
int primes[maxn];      
int ind = 0;

void prep() {

    for (int i = 0; i < maxn; ++i) spf[i] = 0;
    ind = 0;

    for (int i = 2; i < maxn; ++i) {
        if (spf[i] == 0) {
            spf[i] = i;
            primes[ind++] = i;
        }

        for (int j = 0; j < ind; ++j) {
            int p = primes[j];
            long long x = 1LL * i * p;
            if (x >= maxn) break;
            spf[x] = p;
            if (p == spf[i]) break; 
        }
    }
}

vector<pair<int,int>> factorize(int n) {
    vector<pair<int,int>> fac;
    if (n <= 1) return fac;
    while (n > 1) {
        int p = spf[n];
        if (p == 0) { 

            p = n;
        }
        int cnt = 0;
        while (n % p == 0) {
            n /= p;
            ++cnt;
        }
        fac.emplace_back(p, cnt);
    }
    return fac;
}
vector<int> divs_(int n) {
    vector<pair<int,int>> fac = factorize(n);
    vector<int> divs = {1};
    for (auto [p, e] : fac) {
        vector<int> divs_;
        for (int d : divs) {
            int cur = 1;
            for (int i = 0; i <= e; ++i) {
                divs_.push_back(d * cur);
                cur *= p;
            }
        }
        divs.swap(divs_);
    }
    sort(divs.begin(), divs.end(), greater<int>());
    return divs;
}
int cnt_[maxn];
int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    for(int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    prep();

    for(int i = 1; i <= n; i++) {
        auto divs = divs_(a[i]);

        for(int j : divs) {
            if(cnt_[j] > 0) {
                maxl[i] = max(maxl[i], j);
            }
        }

        for(int j : divs) {
            cnt_[j] = 1;    
        }
    }

    fill(cnt_, cnt_ + maxn, 0);

    for(int i = n; i >= 1; i--) {
        auto divs = divs_(a[i]);
        for(int j : divs) {
            if(cnt_[j] > 0) {
                maxr[i] = max(maxr[i], j); 
            }
        }
        for(int j : divs) {
            cnt_[j] = 1;    
        }
    }

    for(int i = 2; i <= n; i++) {
        maxl[i] = max(maxl[i], maxl[i - 1]);
    }
    for(int i = n - 1; i >= 1; i--) {
        maxr[i] = max(maxr[i], maxr[i + 1]);
    }

    int ans = 0;

    for(int i = 2; i <= n - 2; i++) {
        ans = max(ans, maxl[i] + maxr[i + 1]);
    }
    cout << ans;
}